cats = {'pi05': [], 'tau_sweep': [], 'crm_baseline': [], 'vla_only': [], 'k2mean': [], 'reconvla': [], 'adapt': [], 'random_sel': [], 'ksweep': [], 'obs_norm': [], 'other': []}
for eid, exp in preparing:
    if 'pi05' in eid:
        cats['pi05'].append(eid)
